/* MONDO — contenus pédagogiques locaux. Aucune requête ni API. */
const CATEGORIES = {
 geo:{label:'Géopolitique',icon:'🌍',tone:'violet',short:'Comprendre les rapports de force'},
 hist:{label:'Histoire',icon:'🏛️',tone:'peach',short:'Relier hier et aujourd’hui'},
 eco:{label:'Économie',icon:'📊',tone:'mint',short:'Décrypter les mécanismes'},
 ideas:{label:'Sciences & idées',icon:'🧠',tone:'sky',short:'Cultiver un regard critique'}
};
const P=(title,body,insight,visual=null,extra={})=>({title,body,insight,visual,...extra});
const V=(id,alt,caption)=>({id,alt,caption});
const Q=(text,options,correct,why)=>({text,options,correct,why});
const L=(id,cat,level,title,desc,emoji,pages,questions)=>({id,cat,level,title,desc,emoji,minutes:pages.length>=7?12:7+level,premium:pages.length>=7,pages,questions});
const LESSONS=[
L('ormuz','geo',1,'Pourquoi le détroit d’Ormuz est stratégique','Le passage où la géographie devient une force économique','🚢',[
 P('Un passage minuscule, des effets planétaires','Imagine qu’une partie majeure de l’approvisionnement pétrolier mondial soit contrainte de passer par un unique couloir maritime. Un incident local peut alors affecter les transporteurs, les assureurs, les raffineries et, finalement, les prix. Le passage relie le golfe Persique, à l’ouest, au golfe d’Oman, à l’est. Il est bordé par l’Iran au nord et Oman au sud. Voilà pourquoi Ormuz est un point de passage stratégique : son importance ne vient pas de sa taille, mais de la concentration des flux.','Un « point d’étranglement » maritime concentre un risque mondial.',V('o-hero','Carte de localisation montrant l’Iran au nord, Oman et les Émirats arabes unis au sud, le golfe Persique à l’ouest et le golfe d’Oman à l’est.','Localise Ormuz : entre l’Iran et Oman, sur la seule sortie maritime du golfe Persique.'),{tag:'LE DÉCLIC · 01'}),
 P('Lis la carte comme un stratège','À l’ouest se trouve le golfe Persique, bordé par plusieurs grands producteurs d’hydrocarbures. À l’est, le golfe d’Oman ouvre la route vers l’océan Indien. Le détroit se situe entre l’Iran, au nord, et la péninsule de Musandam appartenant à Oman, au sud. Pour une grande partie des exportations maritimes des pays du Golfe, c’est la sortie naturelle vers les marchés mondiaux.','Sur une carte, demande-toi toujours ce qui circule, entre qui, et par où.',V('o-map','Vue rapprochée du détroit d’Ormuz, avec la péninsule de Musandam au sud et la côte iranienne au nord.','Zoom sur le passage entre la côte iranienne et la péninsule de Musandam.'),{tag:'COMPRENDRE L’ESPACE · 02'}),
 P('Ce que signifie vraiment « 20 millions »','En 2025, environ 20 millions de barils de pétrole et de produits pétroliers traversaient le détroit chaque jour en moyenne, d’après l’Agence internationale de l’énergie. C’est un ordre de grandeur comparable à un cinquième de la demande mondiale de pétrole. Le gaz naturel liquéfié compte aussi : en 2025, près de 20 % du commerce mondial de GNL empruntait ce corridor. Ces chiffres décrivent une année de référence, pas le trafic en temps réel.','Une statistique utile doit toujours préciser son unité, sa période et son périmètre.',V('o-volume','Infographie comparant les volumes de pétrole et de GNL passés par Ormuz en 2025.','Sources : AIE, données annuelles 2025.'),{tag:'LES ORDRES DE GRANDEUR · 03'}),
 P('Pourquoi l’Asie regarde particulièrement Ormuz','Une large majorité des hydrocarbures transportés par ce passage se dirige vers l’Asie. Les économies importatrices y sont très sensibles parce que leurs raffineries, usines et producteurs d’électricité dépendent de livraisons régulières. Mais un choc ne reste pas localisé aux acheteurs directs : le pétrole se négocie sur des marchés mondiaux, et un renchérissement peut se transmettre à des pays qui n’importent pas directement du golfe Persique.','Distingue « qui achète le pétrole » de « qui subit la variation de prix ». ',V('o-routes','Schéma des routes maritimes reliant le golfe Persique aux acheteurs asiatiques et aux marchés mondiaux.','Flux commerciaux stylisés, sans proportions géographiques.'),{tag:'EFFETS EN CHAÎNE · 04'}),
 P('Pourquoi ne pas simplement passer ailleurs ?','Certaines infrastructures terrestres permettent d’exporter du pétrole sans franchir le détroit, notamment en Arabie saoudite et aux Émirats arabes unis. Mais ces alternatives n’ont pas la capacité de remplacer instantanément tous les flux maritimes. Elles n’acheminent pas non plus de la même manière chaque produit, notamment le gaz liquéfié. Un « détour » peut impliquer des terminaux, des pipelines et des ports supplémentaires : chacun possède ses propres contraintes.','Une route de secours ne rend pas automatiquement une route principale remplaçable.',V('o-alternatives','Comparaison visuelle entre la route maritime principale et des alternatives terrestres limitées.','Capacités alternatives : partielles, non substituables à 100 %.'),{tag:'LES LIMITES DES ALTERNATIVES · 05'}),
 P('Comment une crise locale devient un prix mondial','Il n’est pas nécessaire qu’un détroit soit totalement fermé pour que les prix bougent. Une menace peut suffire à augmenter les primes d’assurance, les coûts de transport ou la peur d’une livraison retardée. Les négociants réévaluent l’offre future, les entreprises ajustent leurs achats et les marchés réagissent aux anticipations. Le mécanisme combine risque réel et perception du risque ; il ne garantit pas une hausse identique des prix dans tous les pays.','Le prix de l’énergie intègre aussi ce que les acteurs redoutent pour demain.',V('o-chain','Chaîne causale du risque géopolitique aux coûts de transport puis aux prix de l’énergie.','Transmission possible, pas automatique.'),{tag:'LE MÉCANISME · 06'}),
 P('Mets-toi dans la peau d’un décideur','Tu diriges une entreprise européenne qui consomme beaucoup d’énergie. Une information annonce des tensions dans le Golfe, mais aucun blocage n’est confirmé. Faut-il attendre, acheter à l’avance ou couvrir une partie des prix ? Il n’existe pas de réponse unique : tout dépend des stocks, des contrats, de la trésorerie et de ta tolérance au risque. Le réflexe important consiste à séparer trois éléments : le fait vérifié, le scénario possible et la décision à prendre.','La géopolitique aide à préparer des scénarios, pas à prédire l’avenir.',V('o-decision','Trois colonnes : fait confirmé, risque possible et décision proportionnée.','Un cadre simple pour analyser une crise.'),{tag:'PASSER À LA PRATIQUE · 07'}),
 P('Ce que tu dois pouvoir expliquer demain','Ormuz relie le golfe Persique au golfe d’Oman. Sa position concentre une quantité majeure de pétrole et de GNL à l’échelle mondiale. Des solutions de contournement existent, mais restent partielles. Enfin, les marchés réagissent non seulement aux interruptions réelles, mais aussi aux risques anticipés. Si tu peux raconter cette chaîne sans apprendre de chiffres par cœur, tu as compris l’essentiel.','La phrase à retenir : un point d’étranglement transforme un risque local en enjeu global.',V('o-recap','Récapitulatif en trois étapes : passage maritime, énergie mondiale et risque sur les prix.','La logique du détroit en trois idées.'),{tag:'LE RÉCAP · 08',sources:[['Agence internationale de l’énergie, dossier Ormuz','https://www.iea.org/about/strait-of-hormuz'],['EIA, rôle du détroit dans le transport de pétrole','https://www.eia.gov/todayinenergy/detail.php?id=65504']]})],[
 Q('Que relie directement le détroit d’Ormuz ?',['La mer Rouge et la Méditerranée','Le golfe Persique et le golfe d’Oman','L’Atlantique et le Pacifique','La mer Noire et la Méditerranée'],1,'Il constitue le débouché maritime du golfe Persique vers le golfe d’Oman.'),
 Q('Pourquoi une tension à Ormuz peut-elle affecter l’économie mondiale ?',['Elle fixe automatiquement les taux directeurs','Elle menace des flux pétroliers et gaziers majeurs','Elle bloque toute navigation dans l’océan Indien','Elle efface la demande mondiale de pétrole'],1,'Le détroit concentre des exportations importantes de pétrole et de gaz liquéfié.'),
 Q('Pourquoi les prix peuvent-ils réagir sans fermeture effective ?',['Les anticipations de risque et les coûts peuvent changer','Un détroit impose un prix légal mondial','Tous les stocks pétroliers disparaissent','Les échanges cessent sur tous les continents'],0,'Marchés et assureurs anticipent les difficultés potentielles avant toute interruption complète.'),
 Q('Pourquoi les pipelines ne remplacent-ils pas totalement Ormuz ?',['Leur capacité et leurs débouchés sont limités','Ils transportent du pétrole sans infrastructures','Ils passent tous par l’océan Atlantique','Ils n’existent dans aucun pays du Golfe'],0,'Des routes terrestres existent, mais leur capacité et leur couverture des produits sont limitées.'),
 Q('À quoi correspond l’ordre de grandeur de 20 millions de barils par jour cité dans la leçon ?',['Aux importations de la seule France en 2025','Au trafic annuel d’un seul port européen','Aux flux quotidiens moyens via Ormuz en 2025','Aux réserves de pétrole d’Oman'],2,'L’AIE évalue à environ 20 millions de barils par jour les flux pétroliers moyens à Ormuz en 2025.')]),
L('ue','geo',1,'Qui décide quoi dans l’Union européenne ?','Trois institutions à ne plus confondre','🇪🇺',[
 P('Une architecture partagée','La Commission européenne propose généralement les nouveaux textes législatifs de l’Union et veille à l’application du droit européen. Le Parlement européen, élu au suffrage universel direct, représente les citoyens.','Une proposition n’est pas encore une loi.'),
 P('Les États ont aussi leur voix','Le Conseil de l’Union européenne réunit les ministres des États membres selon le sujet. Il adopte la plupart des lois avec le Parlement. Le Conseil européen, lui, réunit les dirigeants et fixe les grandes orientations politiques.','Conseil de l’UE et Conseil européen : deux institutions différentes.'),
 P('Une décision en plusieurs étapes','La Commission propose ; le Parlement et le Conseil de l’UE discutent, amendent et adoptent dans la procédure législative ordinaire. Les rôles précis varient selon les compétences et les procédures.','Pour comprendre une annonce européenne, demande-toi si elle est proposée, négociée ou adoptée.')],[
 Q('Quelle institution propose généralement les lois européennes ?',['La Banque centrale européenne','La Cour des comptes européenne','La Commission européenne','La Cour européenne des droits de l’homme'],2,'La Commission dispose généralement de l’initiative législative.'),
 Q('Qui représente directement les citoyens de l’Union ?',['Le Parlement européen','Le Conseil européen','La Commission européenne','Le Conseil de l’UE'],0,'Les députés européens sont élus au suffrage universel direct.'),
 Q('Quel organe réunit les chefs d’État ou de gouvernement des pays de l’UE ?',['Le Conseil de l’Union européenne','Le Conseil européen','Le Parlement européen','Le Comité des régions'],1,'Le Conseil européen définit les grandes orientations politiques de l’Union.')]),
L('chine-mer','geo',2,'Pourquoi la mer de Chine méridionale est disputée','Droit maritime, îles et routes commerciales','🧭',[
 P('Un espace très fréquenté','La mer de Chine méridionale se trouve au cœur des routes commerciales de l’Asie orientale. Elle contient des archipels, des ressources halieutiques et des zones susceptibles d’abriter des hydrocarbures. Plusieurs États riverains y revendiquent des espaces maritimes.','Une petite île peut avoir des conséquences juridiques et stratégiques importantes.'),
 P('Le droit de la mer','La convention de l’ONU sur le droit de la mer prévoit notamment une zone économique exclusive allant en principe jusqu’à 200 milles marins à partir des lignes de base. Les droits attachés à une formation maritime dépendent de sa qualification juridique.','Posséder une côte, un rocher ou une île n’ouvre pas nécessairement les mêmes droits.'),
 P('Des revendications qui se chevauchent','Les revendications de plusieurs pays se recouvrent. En 2016, un tribunal arbitral constitué au titre de la Convention a rejeté certains fondements juridiques des revendications chinoises ; Pékin a refusé la sentence. Les tensions mêlent droit, souveraineté et stratégie.','Un jugement juridique ne règle pas automatiquement le rapport de force politique.')],[
 Q('Que signifie ZEE ?',['Zone économique exclusive','Zone d’exclusion européenne','Zone écologique étatique','Zone d’échange énergétique'],0,'La ZEE est une notion centrale du droit de la mer.'),
 Q('Quelle portée générale est associée à une ZEE ?',['12 milles marins','50 milles marins','200 milles marins','1 000 milles marins'],2,'La limite habituelle maximale est de 200 milles marins sous réserve des règles applicables.'),
 Q('Qu’a fait le tribunal arbitral de 2016 ?',['Il a attribué toutes les îles à un seul pays','Il a examiné certains droits et revendications selon le droit de la mer','Il a créé une nouvelle organisation militaire','Il a fermé la mer au commerce'],1,'La sentence concernait des questions de droit de la mer, sans résoudre toutes les souverainetés.')]),
L('sahel','geo',2,'Comprendre les crises du Sahel','Quand climat, sécurité et institutions s’entremêlent','🌵',[
 P('Une région, pas un pays','Le Sahel désigne une bande semi-aride au sud du Sahara. Il traverse plusieurs États aux histoires et situations différentes. Sa géographie conditionne les activités agricoles et pastorales, mais n’explique pas à elle seule les conflits.','Éviter de parler du Sahel comme d’un bloc homogène.'),
 P('Des causes qui se superposent','Insécurité, gouvernance fragile, pauvreté, tensions locales et déplacements de population peuvent se renforcer. Des groupes armés exploitent parfois des conflits préexistants ; les politiques publiques et les réponses militaires ont des effets variables selon les pays.','Un conflit a rarement une cause unique.'),
 P('Le rôle des acteurs extérieurs','Des organisations régionales et des puissances étrangères interviennent par la diplomatie, l’aide ou la coopération sécuritaire. Les alliances ont évolué, ce qui oblige à distinguer les grandes tendances historiques de la situation du moment.','Pour analyser une crise, identifie les acteurs locaux avant les acteurs extérieurs.')],[
 Q('Que désigne le terme « Sahel » ?',['Un État d’Afrique du Nord','Une bande géographique au sud du Sahara','Un fleuve d’Afrique centrale','Une alliance militaire permanente'],1,'Le Sahel est une région qui traverse plusieurs pays.'),
 Q('Quelle analyse est la plus pertinente pour un conflit sahélien ?',['Une seule cause climatique suffit','Seule la politique étrangère importe','Plusieurs facteurs locaux et régionaux interagissent','Les frontières n’ont aucun rôle'],2,'Les facteurs sécuritaires, politiques, sociaux et environnementaux peuvent interagir.'),
 Q('Pourquoi faut-il éviter de généraliser à tous les pays du Sahel ?',['Leurs situations politiques et sociales diffèrent','Ils ont tous la même constitution','Ils partagent tous une langue unique','Ils ont exactement la même économie'],0,'Chaque État possède des institutions, une histoire et des enjeux propres.')]),
L('taiwan','geo',3,'Taïwan : comprendre un enjeu mondial','Statut politique, détroit et puces électroniques','🛰️',[
 P('Une question politique non résolue','L’île de Taïwan dispose de ses propres institutions et d’un gouvernement élu. La République populaire de Chine revendique Taïwan comme faisant partie de son territoire. Le statut international de l’île est une source majeure de tensions diplomatiques.','Distinguer gouvernement effectif, reconnaissance diplomatique et revendication territoriale.'),
 P('Une géographie stratégique','Le détroit de Taïwan sépare l’île de la Chine continentale. Il se situe dans une zone maritime et aérienne majeure en Asie orientale. Les positions des acteurs régionaux et des États-Unis font de cette question un enjeu de sécurité plus large.','Une crise régionale peut avoir des répercussions internationales.'),
 P('Pourquoi les semi-conducteurs comptent','Taïwan occupe une place essentielle dans la fabrication mondiale de certaines puces avancées. Cette concentration crée des dépendances dans l’électronique, l’automobile et les équipements industriels. Elle ne résume toutefois pas tous les enjeux du dossier.','Une chaîne d’approvisionnement peut être aussi stratégique qu’une route maritime.')],[
 Q('Quelle affirmation décrit le mieux la situation de Taïwan ?',['L’île n’a aucune institution propre','Elle possède ses institutions tandis que Pékin revendique sa souveraineté','Elle est administrée par l’ONU','Elle est un État membre de l’UE'],1,'Taïwan est gouvernée par ses propres institutions et sa souveraineté est contestée par Pékin.'),
 Q('Quel secteur industriel rend Taïwan particulièrement important ?',['L’extraction de charbon','La production de pétrole brut','La fabrication de semi-conducteurs avancés','La construction de barrages'],2,'La fabrication de puces avancées est fortement concentrée sur l’île.'),
 Q('Quelle dépendance une crise pourrait-elle mettre en évidence ?',['Une dépendance technologique dans les chaînes mondiales','L’absence de commerce international','La disparition des monnaies nationales','La fin du transport aérien'],0,'De nombreuses industries dépendent de composants produits dans des chaînes mondialisées.')]),
L('brics','geo',3,'BRICS et G7 : deux logiques différentes','Alliances politiques ou forums de coopération ?','🤝',[
 P('Le G7, un forum historique','Le G7 réunit sept économies industrialisées : Allemagne, Canada, États-Unis, France, Italie, Japon et Royaume-Uni, avec participation de l’Union européenne. Il coordonne des positions mais n’est pas une organisation supranationale qui impose ses lois.','Le G7 est un forum de concertation, pas un gouvernement mondial.'),
 P('Les BRICS, une coalition évolutive','L’acronyme désignait initialement le Brésil, la Russie, l’Inde et la Chine ; l’Afrique du Sud a ensuite rejoint le groupe. Sa composition s’est élargie par la suite. Les États membres ne partagent pas nécessairement les mêmes intérêts géopolitiques.','Un groupe peut peser collectivement sans adopter une position unique.'),
 P('Comparer sans caricaturer','Les deux forums cherchent à peser sur la gouvernance mondiale, mais leurs histoires, compositions et priorités diffèrent. Pour juger une déclaration, il faut regarder la date, les signataires et le degré d’engagement réel.','Ne pas confondre communiqué diplomatique et obligation juridique.')],[
 Q('Lequel de ces pays faisait partie des quatre BRIC initiaux ?',['L’Afrique du Sud','L’Inde','L’Égypte','L’Arabie saoudite'],1,'Le sigle BRIC regroupait initialement Brésil, Russie, Inde et Chine.'),
 Q('Quelle caractéristique décrit correctement le G7 ?',['Une organisation votant des lois mondiales','Une union douanière unique','Un forum de coordination politique','Une banque centrale commune'],2,'Les conclusions du G7 n’ont pas, par elles-mêmes, la force de lois mondiales.'),
 Q('Pourquoi les positions des BRICS ne sont-elles pas forcément identiques ?',['Leurs membres ont des intérêts nationaux différents','Ils n’ont jamais tenu de réunion','Ils utilisent tous la même monnaie','Tous sont membres de l’Union européenne'],0,'Les intérêts des États membres peuvent diverger fortement.')]),
L('rome','hist',1,'Comment Rome est passée de la République à l’Empire','Institutions, conflits et pouvoir personnel','🏛️',[
 P('La République romaine','Après la période monarchique, Rome développa une République fondée sur des magistratures, un Sénat influent et des assemblées civiques. Le pouvoir n’était pourtant pas partagé de manière égale entre tous les habitants.','République ne signifie pas démocratie universelle au sens moderne.'),
 P('Les crises de la fin de la République','Les conquêtes, les inégalités et les rivalités entre chefs militaires fragilisèrent les institutions. Jules César concentra le pouvoir avant son assassinat en 44 av. J.-C. Une nouvelle phase de guerre civile s’ensuivit.','La puissance militaire peut déstabiliser des institutions politiques.'),
 P('Auguste et le principat','Octavien, devenu Auguste, établit un nouveau régime en 27 av. J.-C. Il conserva des formes républicaines tout en accumulant une autorité décisive. On situe généralement au début de son règne la naissance de l’Empire romain.','Une transformation politique peut maintenir les anciens noms tout en changeant la réalité du pouvoir.')],[
 Q('Quel personnage fut assassiné en 44 av. J.-C. ?',['Auguste','Jules César','Néron','Trajan'],1,'Jules César fut tué lors des ides de mars en 44 av. J.-C.'),
 Q('Quelle date marque traditionnellement le début du principat d’Auguste ?',['509 av. J.-C.','44 av. J.-C.','27 av. J.-C.','476 apr. J.-C.'],2,'En 27 av. J.-C., Octavien reçut le titre d’Auguste.'),
 Q('Que montre le passage au principat ?',['Des institutions anciennes peuvent subsister avec un pouvoir transformé','Le Sénat disparut immédiatement','Tous les Romains obtinrent le droit de vote','Rome cessa ses conquêtes'],0,'Les formes républicaines furent conservées alors que le pouvoir se concentrait.')]),
L('revolution','hist',1,'Pourquoi 1789 a changé la France','États généraux, Bastille et droits','📜',[
 P('Une monarchie en crise','À la fin des années 1780, l’État royal français fait face à de graves difficultés financières. Les tensions sociales et la contestation des privilèges aggravent la crise. Louis XVI convoque les États généraux pour mai 1789.','Les révolutions naissent souvent d’une convergence de crises.'),
 P('De la représentation à la rupture','Les députés du tiers état se proclament Assemblée nationale en juin. La prise de la Bastille, le 14 juillet, devient un symbole majeur. En août, l’Assemblée abolit des privilèges et adopte la Déclaration des droits de l’homme et du citoyen.','La rupture politique se construit par étapes, pas en un seul jour.'),
 P('Un héritage durable et complexe','La Révolution redéfinit la souveraineté, les droits et la citoyenneté. Elle traverse aussi de fortes violences et des changements de régime. Son héritage doit être étudié dans sa complexité, sans la réduire à un récit entièrement positif ou négatif.','Une même période peut produire des droits nouveaux et des violences.')],[
 Q('Pourquoi Louis XVI convoque-t-il les États généraux en 1789 ?',['Pour élire Napoléon','Pour répondre notamment à une crise financière','Pour déclarer la guerre à l’Italie','Pour proclamer l’Empire'],1,'Les difficultés des finances royales jouent un rôle central.'),
 Q('À quelle date a lieu la prise de la Bastille ?',['4 août 1789','21 janvier 1793','14 juillet 1789','18 brumaire an VIII'],2,'La Bastille est prise le 14 juillet 1789.'),
 Q('Quel texte est adopté en août 1789 ?',['La Déclaration des droits de l’homme et du citoyen','Le Code civil','La Constitution de 1958','Le traité de Maastricht'],0,'La Déclaration devient un texte fondateur de la période révolutionnaire.')]),
L('constantinople','hist',2,'1453 : comment Constantinople est tombée','Une capitale, un siège et un changement d’époque','🏰',[
 P('Une ville que l’on croyait imprenable','Pendant plus d’un millénaire, Constantinople est l’une des villes les plus prestigieuses du monde méditerranéen. Capitale de l’Empire romain d’Orient, elle possède de puissantes murailles et bénéficie d’une position spectaculaire entre deux mers. Pourtant, en 1453, son empire est affaibli, son territoire réduit et ses ressources insuffisantes face à une puissance ottomane en expansion. Comprendre la chute exige de regarder à la fois la géographie, la stratégie et les rapports de force.','Une fortification exceptionnelle ne suffit pas si l’équilibre des forces change.',V('c-hero','Illustration originale de Constantinople et de ses remparts au bord du détroit.','Une ville fortifiée entre deux continents.'),{tag:'LE DÉCLIC · 01'}),
 P('Le Bosphore : un atout et une fragilité','La ville contrôle un passage entre la mer Noire et la mer de Marmara, face au monde anatolien. Au nord s’étend la Corne d’Or, un bras de mer qui abrite un port précieux ; à l’ouest, de longues murailles terrestres protègent l’accès à la cité. Cette implantation favorise le commerce et la défense, mais impose de surveiller simultanément les accès par terre et par mer.','Une carte militaire se lit en termes d’obstacles, de flux et de points faibles.',V('c-map','Plan schématique des remparts terrestres, de la Corne d’Or, du Bosphore et de la mer de Marmara.','Schéma simplifié, non à l’échelle.'),{tag:'LIRE LE TERRAIN · 02'}),
 P('Avant 1453, un long affaiblissement','L’Empire byzantin ne s’effondre pas en un seul jour. En 1204, la quatrième croisade s’empare de Constantinople et déstabilise profondément l’Empire. Même après la reprise de la ville en 1261, les territoires et les moyens continuent de se réduire. Au XVe siècle, la pression ottomane rend la situation particulièrement difficile. La prise finale survient donc après une longue histoire de crises, et pas seulement à cause d’un canon particulièrement puissant.','Cherche toujours les causes lentes derrière un événement spectaculaire.',V('c-timeline','Frise 1204, 1261, 1451 et 1453 montrant la montée vers le siège.','Quatre repères pour replacer 1453 dans le temps.'),{tag:'LES CAUSES LONGUES · 03'}),
 P('Mehmed II prépare le siège','Le sultan ottoman Mehmed II veut intégrer Constantinople à son empire et consolider son contrôle sur les voies de passage. En avril 1453, ses forces encerclent la ville, tandis que les défenseurs de l’empereur Constantin XI résistent derrière leurs fortifications. L’attaquant combine artillerie, blocus, logistique et pression continue. Les remparts résistent longtemps, mais les forces qui les défendent sont numériquement et matériellement très contraintes.','Une victoire de siège exige une stratégie complète, pas un seul équipement.',V('c-siege','Schéma des murs byzantins et de l’artillerie ottomane pendant le siège.','Artillerie, fortifications et usure défensive.'),{tag:'LA STRATÉGIE · 04'}),
 P('La Corne d’Or : une bataille de mobilité','Les défenseurs protègent l’entrée de la Corne d’Or à l’aide d’une chaîne destinée à empêcher le passage de navires ennemis. Les Ottomans contournent cette barrière en faisant transporter des bateaux sur la terre ferme, afin de les faire parvenir dans le bras de mer. Cet épisode illustre un principe stratégique : lorsque l’adversaire verrouille l’accès direct, chercher une autre manière de déplacer ses forces peut modifier l’équilibre du siège.','Une barrière peut être solide et pourtant contournable.',V('c-horn','Schéma simplifié montrant la chaîne de la Corne d’Or et le transport terrestre de navires.','Manœuvre ottomane vers la Corne d’Or.'),{tag:'L’IDÉE DÉCISIVE · 05'}),
 P('29 mai 1453 : la rupture','Après plusieurs semaines de combats, l’assaut ottoman du 29 mai emporte la ville. Constantin XI meurt lors de la défense. La conquête met fin au gouvernement byzantin de Constantinople et ouvre une nouvelle phase de l’histoire de la cité. Mehmed II en fait un centre majeur de son empire, auquel il donne un vaste programme de reconstruction. L’épisode est considérable, mais il ne signifie ni la disparition immédiate de tous les héritages romains ni l’arrêt de tous les échanges entre Orient et Occident.','Une conquête peut renverser un pouvoir tout en préservant et transformant des héritages.',V('c-legacy','Avant et après 1453 : une ville qui change de pouvoir et se transforme.','Rupture politique, continuités urbaines et culturelles.'),{tag:'LE TOURNANT · 06'}),
 P('1453 marque-t-il vraiment la fin du Moyen Âge ?','Dans de nombreux manuels, 1453 sert de repère entre Moyen Âge et époque moderne. Ce choix est pratique, mais il ne fait pas basculer instantanément toutes les sociétés européennes dans une nouvelle époque. Les transformations économiques, culturelles et politiques s’étalent sur des décennies. De même, dire que la chute de la ville aurait « fermé » toutes les routes commerciales vers l’Asie simplifie abusivement des échanges qui ont continué sous des formes différentes.','Une grande date organise le récit : elle ne remplace pas une explication.',V('c-period','Infographie opposant une date-repère à des changements historiques progressifs.','La périodisation est un outil, pas une frontière absolue.'),{tag:'LE REGARD CRITIQUE · 07'}),
 P('Ce que tu sais maintenant raconter','La situation de Constantinople la rend stratégique, mais vulnérable à un encerclement. Son Empire est affaibli de longue date. Mehmed II associe artillerie, logistique et manœuvres pour prendre la ville le 29 mai 1453. Enfin, la conquête clôt l’Empire byzantin tout en lançant une nouvelle étape ottomane. Si tu peux articuler ces quatre points et nuancer l’idée de « fin du Moyen Âge », tu as compris bien plus qu’une date.','À retenir : géographie + affaiblissement + stratégie = basculement politique.',V('c-recap','Synthèse des quatre facteurs de la chute de Constantinople.','Les quatre idées essentielles.'),{tag:'LE RÉCAP · 08',sources:[['Metropolitan Museum — art ottoman et conquête','https://www.metmuseum.org/essays/the-art-of-the-ottomans-before-1600'],['Metropolitan Museum — Constantinople et Byzance','https://www.metmuseum.org/fr/essays/byzantium-ca-330-1453']]})],[
 Q('Qui conquiert Constantinople en 1453 ?',['Charlemagne','Mehmed II','Napoléon Ier','Saladin'],1,'Le sultan Mehmed II dirige la conquête ottomane de la ville.'),
 Q('Quel empire perd sa capitale en 1453 et cesse alors d’exercer le pouvoir depuis elle ?',['L’Empire carolingien','L’Empire romain d’Occident','L’Empire byzantin','L’Empire austro-hongrois'],2,'Constantinople était la capitale de l’Empire romain d’Orient, ou byzantin.'),
 Q('Pourquoi faut-il nuancer l’idée que 1453 « termine » le Moyen Âge ?',['Les transformations historiques s’étalent dans le temps','La ville n’a jamais existé','Le commerce mondial s’arrête ce jour-là','Le siège ne s’est pas produit'],0,'Les périodes historiques sont des conventions utiles mais ne commencent pas partout à une date unique.'),
 Q('Quel espace portuaire les Ottomans cherchent-ils à atteindre malgré une chaîne défensive ?',['La Corne d’Or','Le golfe de Gascogne','La mer Caspienne','Le golfe Persique'],0,'Des navires furent transportés par voie terrestre pour pénétrer dans la Corne d’Or.'),
 Q('Quel ensemble de facteurs explique le mieux la prise de la ville ?',['Le seul effet d’une arme nouvelle','Une épidémie qui vide la région','La combinaison d’un empire affaibli, du siège et de la logistique','Un accord commercial négocié sans combats'],2,'L’artillerie joue un rôle, mais l’issue dépend aussi des moyens, de l’encerclement et de la situation antérieure.')]),
L('1914','hist',2,'1914 : pourquoi la guerre devient mondiale','De Sarajevo au jeu des alliances','💣',[
 P('Une Europe sous tension','Avant 1914, les rivalités entre puissances, le nationalisme, la militarisation et les tensions dans les Balkans rendent la situation explosive. Les alliances créent des obligations et des attentes de soutien, mais n’automatisent pas toutes les décisions.','L’événement déclencheur n’est pas nécessairement la cause profonde.'),
 P('L’attentat de Sarajevo','Le 28 juin 1914, l’archiduc François-Ferdinand d’Autriche est assassiné à Sarajevo. L’Autriche-Hongrie entre en conflit avec la Serbie ; des mobilisations et déclarations de guerre s’enchaînent pendant la crise de juillet.','Une crise diplomatique peut s’aggraver par une succession de décisions.'),
 P('Une guerre qui dépasse l’Europe','Les empires coloniaux, les routes maritimes et l’entrée de nouvelles puissances étendent le conflit. L’expression « guerre mondiale » reflète aussi l’implication de combattants et de ressources venus de territoires extra-européens.','Comprendre la guerre exige de regarder les empires, pas seulement les capitales européennes.')],[
 Q('Quel événement déclenche la crise de l’été 1914 ?',['La chute de Berlin','L’assassinat de François-Ferdinand à Sarajevo','La signature du traité de Versailles','La révolution russe'],1,'L’attentat du 28 juin 1914 ouvre la crise diplomatique.'),
 Q('Quelle date correspond à l’attentat de Sarajevo ?',['28 juin 1914','11 novembre 1918','1er septembre 1939','8 mai 1945'],0,'L’archiduc est assassiné le 28 juin 1914.'),
 Q('Pourquoi la guerre concerne-t-elle aussi d’autres continents ?',['Tous les pays sont neutres','Les empires coloniaux et les échanges mondiaux l’étendent','Les bateaux ont disparu','Les alliances européennes sont interdites'],1,'Les empires coloniaux mobilisent des hommes et des ressources au-delà de l’Europe.')]),
L('inde','hist',3,'L’indépendance de l’Inde et la partition','Une victoire politique et un drame humain','🕊️',[
 P('Une longue lutte anticoloniale','Le mouvement pour l’indépendance de l’Inde britannique prend de multiples formes. Gandhi promeut la non-violence et la désobéissance civile ; d’autres acteurs défendent des voies différentes. Le contexte de la Seconde Guerre mondiale modifie les rapports de force.','Un mouvement historique n’est jamais l’œuvre d’un seul individu.'),
 P('L’année 1947','En août 1947, l’Inde et le Pakistan deviennent indépendants. La partition du Raj britannique crée deux États, dans un contexte de divisions politiques et religieuses. Les frontières sont établies dans l’urgence et des millions de personnes se déplacent.','Une indépendance peut s’accompagner d’un bouleversement des frontières.'),
 P('Un héritage toujours sensible','Les violences de la partition causent de très nombreuses morts et des migrations massives. Les relations entre l’Inde et le Pakistan restent marquées par cette histoire, notamment autour du Cachemire. Il faut distinguer la décolonisation de la manière dont elle s’est déroulée.','Un succès d’émancipation peut coexister avec une catastrophe humanitaire.')],[
 Q('En quelle année l’Inde et le Pakistan accèdent-ils à l’indépendance ?',['1919','1939','1947','1962'],2,'La partition et les indépendances ont lieu en août 1947.'),
 Q('Quelle méthode est particulièrement associée à Gandhi ?',['La désobéissance civile non violente','La guerre de conquête','La colonisation de l’Europe','La création de l’OTAN'],0,'Gandhi défend des campagnes de mobilisation non violente.'),
 Q('Quelle conséquence immédiate caractérise la partition ?',['L’absence totale de migration','D’immenses déplacements de population','La disparition de toutes les frontières','L’unification de toute l’Asie du Sud'],1,'La partition entraîne des migrations forcées ou précipitées et des violences.')]),
L('non-alignes','hist',3,'La guerre froide vue par les non-alignés','Un monde qui ne se résume pas à Washington et Moscou','🌐',[
 P('Le monde bipolaire, une simplification','Après 1945, la rivalité entre États-Unis et URSS structure une grande partie de la politique mondiale. Pourtant, de nombreux États nouvellement indépendants cherchent à préserver leur autonomie plutôt qu’à adhérer durablement à un camp.','Une grande rivalité ne supprime pas les intérêts des autres pays.'),
 P('Bandung et Belgrade','La conférence de Bandung, en 1955, réunit des pays asiatiques et africains autour de préoccupations anticoloniales. En 1961, le mouvement des non-alignés tient son premier sommet à Belgrade. Les participants n’ont pas des politiques identiques.','Le non-alignement est une orientation diplomatique, pas une neutralité parfaite.'),
 P('Des choix parfois contradictoires','Certains États non-alignés reçoivent une aide militaire ou économique des superpuissances. Ils peuvent chercher à négocier, arbitrer ou préserver une marge de manœuvre. La notion de « tiers-monde » a aussi eu une histoire politique spécifique.','Regarder les stratégies concrètes plutôt que les seules étiquettes.')],[
 Q('En quelle année a lieu la conférence de Bandung ?',['1945','1955','1965','1975'],1,'La conférence afro-asiatique se tient en 1955.'),
 Q('Où se tient le premier sommet des non-alignés en 1961 ?',['Belgrade','Paris','Washington','Moscou'],0,'Le premier sommet officiel du mouvement a lieu à Belgrade.'),
 Q('Le non-alignement signifie-t-il toujours l’absence de relations avec les superpuissances ?',['Oui, il interdit le commerce','Oui, il interdit toute diplomatie','Non, les États peuvent coopérer sans rejoindre un bloc','Non, il implique de rejoindre les deux blocs'],2,'L’autonomie stratégique n’exclut pas les échanges avec l’un ou l’autre camp.')]),
L('inflation','eco',1,'L’inflation, sans jargon','Pourquoi les prix montent-ils ?','🛒',[
 P('Ce que mesure l’inflation','L’inflation est une augmentation générale et durable du niveau des prix. On l’observe à l’aide d’indices représentatifs d’un panier de biens et de services. Le prix de chaque produit ne varie pas forcément au même rythme.','Une hausse du prix d’un seul produit n’est pas, à elle seule, de l’inflation.'),
 P('Plusieurs mécanismes possibles','Une demande plus forte que les capacités de production peut pousser les prix à la hausse. Des coûts de production ou d’énergie plus élevés peuvent aussi être répercutés sur les clients. Les anticipations influencent salaires et décisions de prix.','L’inflation peut avoir plusieurs causes simultanées.'),
 P('Inflation et désinflation','Si l’inflation ralentit de 6 % à 2 %, les prix augmentent encore en moyenne, mais moins vite. Une baisse générale du niveau des prix correspond à la déflation, notion différente.','Désinflation = ralentissement de la hausse, pas baisse des prix.')],[
 Q('Que mesure l’inflation ?',['L’évolution générale du niveau des prix','Le prix d’un seul produit','Le nombre de magasins','Le volume de population'],0,'L’inflation porte sur l’évolution d’un ensemble de prix.'),
 Q('Quand l’inflation passe de 6 % à 2 %, que se passe-t-il ?',['Les prix baissent de 4 %','Les prix continuent généralement d’augmenter, moins vite','Les prix sont figés','Le salaire réel double'],1,'Une inflation positive de 2 % implique encore une hausse moyenne des prix.'),
 Q('Quel choc peut alimenter l’inflation par les coûts ?',['Une baisse du coût de l’énergie','Une augmentation de la productivité','Une forte hausse du prix des intrants énergétiques','Une baisse générale des loyers'],2,'Des intrants plus chers peuvent augmenter les coûts de production.')]),
L('taux','eco',1,'Comment les taux d’intérêt freinent l’inflation','Du taux de la BCE au pouvoir d’achat','🏦',[
 P('Le paradoxe : ralentir pour stabiliser','Quand les prix augmentent trop vite, une banque centrale peut relever ses taux directeurs. À première vue, cela semble étrange : rendre le crédit plus cher alors que ménages et entreprises subissent déjà la hausse des prix. Pourtant, la logique est de réduire progressivement certaines dépenses financées par emprunt, afin que la demande exerce moins de pression sur les prix. L’objectif n’est pas de faire disparaître toute hausse des prix, mais de ramener l’inflation vers la cible.','Hausser les taux agit sur le rythme de la demande, pas directement sur l’étiquette des prix.',V('e-hero','Schéma du lien entre taux directeurs, demande et hausse des prix.','Le taux d’intérêt agit comme un frein, pas comme un interrupteur.'),{tag:'LE DÉCLIC · 01'}),
 P('Taux directeur ≠ taux immobilier','Dans la zone euro, la Banque centrale européenne pilote des taux directeurs qui influencent les coûts de financement à court terme et les anticipations. Les banques transmettent une partie de ces variations aux taux proposés pour les prêts et les dépôts. Mais un prêt immobilier dépend aussi de sa durée, de la concurrence, du risque et du financement de la banque. Le taux directeur n’est donc pas le taux contractuel de chaque emprunteur.','Le mécanisme est indirect : banque centrale → banques → conditions financières.',V('e-transmission','Diagramme en trois niveaux : BCE, banques puis ménages et entreprises.','La transmission passe par les conditions de financement.'),{tag:'LES ACTEURS · 02'}),
 P('Une hausse des taux change les arbitrages','Imagine une entreprise qui hésite à financer une nouvelle usine, ou un ménage qui souhaite acheter un logement. Lorsque le coût de l’emprunt augmente, certains projets deviennent moins rentables ou moins accessibles. En parallèle, une épargne mieux rémunérée peut rendre l’achat immédiat moins attrayant. Additionnés, ces arbitrages modèrent consommation et investissement. Cela ne signifie pas que tout le monde réagit de la même manière. Il faut aussi distinguer taux nominal et taux réel : un rendement nominal de 3 % avec 4 % d’inflation anticipée représente environ −1 % de rendement réel attendu. C’est ce pouvoir d’achat futur qui compte pour beaucoup de décisions.','L’outil monétaire influence des millions de décisions individuelles.',V('e-decisions','Balance visuelle entre emprunter, dépenser et épargner lorsque les taux augmentent.','Des choix différents pour les ménages et les entreprises.'),{tag:'LES DÉCISIONS · 03'}),
 P('Exemple concret : le coût d’un crédit','Pour un emprunt fictif de 200 000 € remboursé par mensualités constantes sur 20 ans, un taux annuel fixe de 2 % correspond à environ 1 012 € par mois, contre environ 1 320 € à 5 %. Ces montants illustratifs n’incluent ni assurance ni frais. L’écart dépasse 300 € mensuels : certains acheteurs réduisent leur budget ou reportent leur projet. C’est une manière concrète de voir comment une hausse des taux peut refroidir une partie de la demande.','À montant emprunté identique, une hausse du taux augmente la mensualité.',V('e-credit','Deux barres comparant les mensualités d’un prêt de 200 000 euros sur 20 ans à 2 et 5 pour cent.','Simulation illustrative, hors assurance et frais.'),{tag:'L’EXEMPLE CHIFFRÉ · 04'}),
 P('De la demande aux prix : un enchaînement','Si les achats et les investissements ralentissent, les entreprises peuvent avoir davantage de difficulté à augmenter leurs prix : la pression de la demande est moins forte. En outre, une banque centrale crédible peut influencer les anticipations de prix et de salaires. Ce double canal — activité économique et anticipations — contribue à réduire l’inflation sur la durée. L’effet n’est ni instantané ni uniforme ; un choc énergétique peut faire monter les prix malgré des taux élevés.','Les taux réduisent les pressions inflationnistes ; ils ne neutralisent pas chaque choc.',V('e-chain','Chaîne de transmission : taux en hausse, crédit plus cher, demande modérée, inflation qui ralentit.','Relation générale, avec délais et incertitudes.'),{tag:'LE MÉCANISME · 05'}),
 P('Désinflation ne veut pas dire baisse des prix','Supposons un indice des prix à 100. Après une hausse annuelle de 6 %, il atteint 106. Si l’année suivante l’inflation tombe à 2 %, l’indice progresse encore à 108,12. Les prix continuent donc d’augmenter, simplement moins vite. Une diminution du niveau général des prix serait de la déflation, notion différente. Cette nuance est essentielle pour comprendre les annonces économiques : une bonne nouvelle sur l’inflation ne signifie pas que les courses redeviennent moins chères.','Une inflation de 2 % reste une hausse des prix de 2 %.',V('e-prices','Graphique de l’indice de prix 100 puis 106 puis 108,12 malgré la désinflation.','Exemple pédagogique avec une inflation de 6 % puis de 2 %.'),{tag:'NE PAS CONFONDRE · 06'}),
 P('Pourquoi la BCE attend avant de conclure','Les nouveaux taux ne se transmettent pas immédiatement à tous les crédits. Une partie des ménages a des emprunts à taux fixes ; les contrats sont renouvelés progressivement. Les entreprises disposent parfois de trésorerie ou de prêts déjà négociés. Enfin, les prix dépendent aussi de l’énergie, des salaires, des échanges et de chocs d’offre. Les taux de marché peuvent également évoluer avant la décision officielle si une hausse était déjà anticipée. La BCE doit donc suivre plusieurs indicateurs et prendre des décisions dans l’incertitude. La cible d’inflation de la BCE est 2 % à moyen terme.','En politique monétaire, le délai de transmission compte autant que la décision.',V('e-delay','Frise des délais entre décision de la BCE, nouveaux crédits, dépenses et inflation.','Transmission progressive et incertaine.'),{tag:'LES LIMITES · 07'}),
 P('La logique à expliquer en trente secondes','Une banque centrale relève ses taux pour rendre le financement généralement plus coûteux et l’épargne parfois plus attractive. Les ménages et les entreprises arbitrent alors différemment : certains achats et investissements ralentissent. Cela peut réduire la pression sur les prix et aider à ancrer les anticipations d’inflation. Mais l’effet passe par les banques, arrive avec retard et ne compense pas toutes les hausses de coûts. Enfin, ralentir l’inflation ne signifie pas faire baisser les prix.','À retenir : taux ↑ → demande moins dynamique → inflation potentiellement plus faible.',V('e-recap','Récapitulatif de la chaîne de transmission de la politique monétaire.','La politique monétaire en une chaîne logique.'),{tag:'LE RÉCAP · 08',sources:[['BCE — mécanisme de transmission monétaire','https://www.ecb.europa.eu/mopo/intro/transmission/html/index.fr.html'],['BCE — Pourquoi faire varier les taux ?','https://www.ecb.europa.eu/ecb-and-you/explainers/html/interest-rates-changes.en.html']]})],[
 Q('Une flambée du gaz augmente les coûts de production et ralentit l’activité. Quel est le dilemme principal pour la BCE ?',['L’inflation peut monter alors que la croissance faiblit : durcir les taux a un coût','La hausse des prix prouve nécessairement que la demande des ménages accélère','La BCE peut rétablir directement l’offre de gaz en relevant les taux','Une baisse immédiate de la demande garantit une baisse de tous les prix'],0,'Un choc d’offre peut simultanément alimenter l’inflation et pénaliser l’activité. La politique monétaire peut contenir les effets persistants, mais elle ne produit pas de gaz et son resserrement peut freiner davantage l’économie.'),
 Q('Une épargne rapporte 3 % sur un an, alors que l’inflation attendue est de 4 %. Quel rendement réel anticipé approximatif cela représente-t-il ?',['Environ +7 %','Environ +1 %','Environ −1 %','Environ −4 %'],2,'Approximation du taux réel : 3 % − 4 % = −1 %. Le rendement nominal est positif, mais le pouvoir d’achat de l’épargne devrait légèrement diminuer si cette inflation se réalise.'),
 Q('La BCE relève son taux directeur de 1 point. Quelle conséquence est la plus défendable à court terme ?',['La mensualité de tous les crédits à taux fixe augmente aussitôt de 1 point','Les nouveaux emprunteurs peuvent payer plus cher, sans changement contractuel sur les anciens prêts fixes','Les banques doivent relever tous leurs prêts exactement de 1 point','Les effets sont forcément les mêmes sur les crédits immobiliers et les crédits aux entreprises'],1,'La transmission n’est ni instantanée ni uniforme. Les nouveaux prêts intègrent les conditions financières du moment ; une mensualité de prêt ancien à taux fixe ne change pas simplement parce que la BCE relève ses taux.'),
 Q('Un indice des prix passe de 100 à 106, puis à 108,12. Quelle hausse cumulée des prix observe-t-on sur les deux années ?',['8,12 %','8,00 %','6,00 %','2,12 %'],0,'L’indice final est 108,12 pour une base de 100 : la hausse cumulée est donc de 8,12 %. Additionner simplement 6 % et 2 % donne 8 %, mais ignore que la deuxième hausse porte sur 106.'),
 Q('La BCE relève ses taux comme prévu, mais les taux de marché bougent peu le jour de l’annonce. Quelle explication est plausible ?',['Les taux de marché ne dépendent jamais des anticipations','L’inflation est devenue nulle lors de la décision','La hausse avait déjà été anticipée et intégrée aux prix de marché','Les banques doivent attendre un an avant de réviser leurs conditions'],2,'Les marchés peuvent réagir avant l’annonce lorsqu’une décision est largement attendue. L’effet immédiat dépend souvent de l’écart entre la décision et les anticipations, pas seulement du changement annoncé.'),
 Q('Une entreprise envisage quatre projets de risque comparable, financés uniquement par emprunt. Lequel devient le moins attractif si le coût du crédit est de 5 % ?',['Rendement attendu 8 % et coût de dette 5 %','Rendement attendu 6 % et coût de dette 5 %','Rendement attendu 7 % et coût de dette 5 %','Rendement attendu 4 % et coût de dette 5 %'],3,'À risque comparable et avant autres effets, un projet rapportant 4 % pour un financement à 5 % a un différentiel négatif de −1 point. Une hausse des taux peut ainsi rendre certains investissements non rentables ou les faire reporter.')]),
L('pib','eco',2,'Ce que le PIB dit — et ne dit pas','Une bonne boussole, pas une mesure du bonheur','📈',[
 P('Mesurer la production','Le produit intérieur brut mesure la valeur ajoutée produite sur un territoire pendant une période, selon les conventions comptables nationales. Il peut être calculé via la production, les revenus ou les dépenses.','Le PIB mesure une activité économique, pas toutes les dimensions de la société.'),
 P('PIB nominal et PIB réel','Le PIB nominal est exprimé aux prix courants. Le PIB réel corrige l’effet de la variation des prix, ce qui aide à observer l’évolution des volumes produits. Une croissance nominale forte peut masquer une hausse des prix.','Toujours se demander : l’économie produit-elle plus ou les prix ont-ils monté ?'),
 P('Les angles morts','Le PIB ne décrit pas directement la répartition des revenus, le travail domestique non rémunéré, ni la qualité de l’environnement. Il reste un indicateur essentiel, mais doit être croisé avec d’autres statistiques.','Un indicateur utile devient trompeur si on lui demande de tout expliquer.')],[
 Q('Que mesure essentiellement le PIB ?',['Le bien-être individuel','La valeur ajoutée produite sur un territoire','Le total du patrimoine mondial','La dette de chaque ménage'],1,'Le PIB agrège la valeur ajoutée selon les conventions des comptes nationaux.'),
 Q('Que permet le PIB réel ?',['Corriger l’effet des prix pour observer les volumes','Mesurer le bonheur','Connaître chaque salaire','Supprimer l’inflation'],0,'Il est construit pour neutraliser les variations de prix dans l’évolution de l’activité.'),
 Q('Quel aspect n’est pas directement mesuré par le PIB ?',['La production marchande','La valeur ajoutée','La répartition des revenus','La dépense publique de consommation'],2,'Le PIB agrégé ne montre pas comment les revenus sont distribués.')]),
L('deficit','eco',2,'Déficit et dette : deux notions à distinguer','Un flux n’est pas un stock','💶',[
 P('Le déficit est un flux','Un déficit public existe lorsque, sur une période donnée, les dépenses publiques dépassent les recettes publiques. C’est une grandeur mesurée sur l’année ou le trimestre, et non une somme accumulée depuis toujours.','Déficit : ce qui se passe pendant une période.'),
 P('La dette est un stock','La dette publique correspond à un encours d’obligations financières à une date donnée, selon une définition statistique précise. Les déficits répétés peuvent augmenter la dette, mais d’autres opérations et ajustements interviennent aussi.','Dette : ce qui est dû à un instant précis.'),
 P('Pourquoi les ratios comptent','On compare souvent déficit et dette au PIB pour les rapporter à la taille de l’économie. Cette comparaison facilite les analyses, mais elle ne suffit pas à juger seule la soutenabilité d’une trajectoire budgétaire.','L’évolution des taux, de la croissance et du solde public importe aussi.')],[
 Q('Le déficit public est principalement…',['Un stock mesuré à une date','Un flux mesuré sur une période','Une mesure du patrimoine privé','Un indice des prix'],1,'Le déficit compare recettes et dépenses sur une période.'),
 Q('La dette publique correspond plutôt…',['À un encours à une date donnée','À une dépense mensuelle unique','Au PIB réel','Au taux de chômage'],0,'La dette mesure un stock d’engagements financiers.'),
 Q('Pourquoi rapporte-t-on souvent la dette au PIB ?',['Pour supprimer la dette','Pour obtenir le taux d’inflation','Pour la comparer à la taille de l’économie','Pour mesurer directement le bonheur'],2,'Le ratio dette/PIB met l’encours en perspective avec l’activité économique.')]),
L('comparatif','eco',3,'L’avantage comparatif expliqué','Pourquoi échanger quand on est meilleur partout ?','⚖️',[
 P('L’intuition trompeuse','Un pays peut être plus productif que son voisin dans toutes les activités et avoir tout de même intérêt au commerce. L’idée d’avantage comparatif s’intéresse au coût d’opportunité : ce à quoi on renonce pour produire une unité supplémentaire.','Ce qui compte n’est pas seulement la performance absolue.'),
 P('Un exemple de spécialisation','Supposons que le pays A puisse produire, par jour, 10 unités de blé ou 5 de tissu ; le pays B, 6 de blé ou 2 de tissu. Pour obtenir un tissu, A renonce à 2 blés, B à 3 blés. A a donc un avantage comparatif dans le tissu.','Compare les renoncements, pas seulement les quantités produites.'),
 P('Le modèle et ses limites','La spécialisation peut augmenter la production totale possible, mais les gains ne sont pas automatiquement répartis équitablement. Coûts de transport, reconversions, institutions et risques stratégiques comptent dans la réalité.','Un modèle éclaire un mécanisme sans décrire toute la société.')],[
 Q('Quel concept est central pour l’avantage comparatif ?',['Le coût d’opportunité','La population totale','La taille de la monnaie','La superficie agricole'],0,'On compare les productions auxquelles chaque acteur renonce.'),
 Q('Si A renonce à 2 blés pour un tissu et B à 3 blés, qui a l’avantage comparatif dans le tissu ?',['B, car 3 est plus grand','Les deux à égalité','A, car son coût d’opportunité est plus faible','Personne ne peut commercer'],2,'A renonce à moins de blé pour produire le tissu.'),
 Q('Quelle limite faut-il garder en tête ?',['Les gains commerciaux sont toujours égaux pour tous','Les gains globaux peuvent être inégalement répartis','Le transport est toujours gratuit','Le commerce élimine tous les risques'],1,'Des secteurs et travailleurs peuvent subir des coûts d’ajustement.')]),
L('change','eco',3,'Pourquoi les devises montent et descendent','Taux de change, attentes et compétitivité','💱',[
 P('Le taux de change est un prix','Un taux de change indique combien d’unités d’une devise s’échangent contre une autre. Si l’euro s’apprécie face au dollar, un euro permet d’obtenir davantage de dollars, toutes choses égales par ailleurs.','Toujours préciser quelle monnaie s’apprécie face à laquelle.'),
 P('Des forces multiples','Taux d’intérêt, inflation attendue, flux d’investissements, commerce et risque influencent les marchés de changes. Une hausse des taux peut soutenir une monnaie, mais l’effet n’est ni mécanique ni garanti.','Les devises réagissent surtout à l’écart entre attentes et nouvelles informations.'),
 P('Des gagnants et des perdants','Une monnaie qui s’apprécie peut rendre les importations moins chères dans la monnaie domestique, mais réduire la compétitivité-prix des exportations. Les effets dépendent des contrats, de la facturation et des chaînes d’approvisionnement.','Un même mouvement de change ne bénéficie pas à tout le monde.')],[
 Q('Si l’euro s’apprécie contre le dollar, un euro achète…',['Moins de dollars','Davantage de dollars','Toujours exactement un dollar','Aucune devise étrangère'],1,'L’appréciation de l’euro signifie qu’il vaut plus de dollars.'),
 Q('Quel facteur peut influencer les taux de change ?',['Les anticipations de taux d’intérêt','La couleur des billets','Le nombre de jours fériés seulement','La forme des pièces'],0,'Les rendements attendus influencent les flux de capitaux et les changes.'),
 Q('Quel effet possible d’une appréciation de la monnaie domestique ?',['Renforcer toujours les exportateurs','Supprimer les importations','Rendre certaines importations moins coûteuses','Faire monter mécaniquement tous les prix'],2,'Il faut moins de monnaie domestique pour acheter un bien tarifé en devises, sous certaines conditions.')]),
L('science','ideas',1,'Comment fonctionne la méthode scientifique','Hypothèse, preuve et possibilité d’erreur','🔬',[
 P('Une question testable','La science cherche des explications confrontables à des observations. Une hypothèse utile doit conduire à des prédictions susceptibles d’être mises à l’épreuve. Les méthodes varient selon les disciplines.','Une idée convaincante n’est pas nécessairement une idée testée.'),
 P('Contrôler les biais','Les chercheurs comparent des mesures, utilisent des groupes de contrôle lorsque c’est pertinent et décrivent leurs protocoles. Reproductibilité, transparence et examen critique renforcent la confiance dans les résultats.','Une expérience isolée est rarement une preuve définitive.'),
 P('Un savoir révisable','Les connaissances scientifiques évoluent avec les nouvelles données. Modifier une théorie face à de meilleures preuves n’est pas une faiblesse : c’est une caractéristique centrale de la démarche.','La science progresse en corrigeant ses erreurs.')],[
 Q('Qu’est-ce qui caractérise une hypothèse scientifique utile ?',['Elle est impossible à discuter','Elle peut être confrontée à des observations','Elle est toujours vraie dès sa formulation','Elle repose uniquement sur une intuition'],1,'Une hypothèse scientifique permet d’envisager des tests empiriques.'),
 Q('À quoi sert la reproductibilité ?',['À vérifier si des résultats résistent à de nouveaux essais','À garantir que chaque étude est parfaite','À éliminer le besoin de mesures','À remplacer toute revue critique'],0,'La reproduction indépendante apporte une vérification supplémentaire.'),
 Q('Que signifie réviser une théorie à la lumière de nouvelles preuves ?',['Que la science est inutile','Que toute opinion est équivalente','Que le savoir scientifique reste ouvert à la correction','Qu’aucune observation n’a de valeur'],2,'L’ajustement aux données fait partie de la démarche scientifique.')]),
L('copernic','ideas',1,'Pourquoi Copernic a bouleversé notre vision du ciel','Passer du géocentrisme à l’héliocentrisme','☀️',[
 P('Deux modèles du monde','Dans le modèle géocentrique traditionnel, la Terre occupe une place centrale dans la description des mouvements célestes. Au XVIe siècle, Copernic formalise un modèle héliocentrique plaçant le Soleil près du centre des mouvements planétaires.','Changer de modèle ne signifie pas disposer d’emblée de toutes les preuves.'),
 P('Des observations décisives','Au début du XVIIe siècle, Galilée observe notamment les phases de Vénus et les satellites de Jupiter. Ces observations remettent en cause certaines versions du géocentrisme. Kepler décrit des orbites elliptiques, améliorant le modèle.','Les progrès résultent d’un travail collectif sur plusieurs générations.'),
 P('Une révolution intellectuelle','La révolution copernicienne transforme la place attribuée à l’être humain dans le cosmos et les méthodes d’étude du ciel. La gravitation newtonienne fournira ensuite un cadre explicatif plus puissant.','Les grandes découvertes combinent théorie, instruments et mesures.')],[
 Q('Quel modèle Copernic défend-il ?',['Le géocentrisme strict','Un modèle héliocentrique','L’absence de planètes','Un univers sans étoiles'],1,'Copernic formalise une représentation centrée sur le Soleil.'),
 Q('Qui établit les lois du mouvement planétaire sur des orbites elliptiques ?',['Kepler','Aristote','Pasteur','Darwin'],0,'Kepler décrit notamment les trajectoires elliptiques des planètes.'),
 Q('Quelle observation de Galilée fragilise certains modèles géocentriques ?',['L’existence de la radioactivité','La dérive des continents','Les phases de Vénus','La structure de l’ADN'],2,'Les phases observées de Vénus sont cohérentes avec un mouvement autour du Soleil.')]),
L('adn','ideas',2,'L’ADN : comment l’information circule','Gènes, protéines et mutations','🧬',[
 P('Une molécule informative','L’ADN est formé de nucléotides dont la séquence porte une information biologique. Chez de nombreux organismes, il est organisé en chromosomes. Un gène correspond à une région d’ADN ayant une fonction biologique identifiable.','L’ADN est une molécule, pas une intention ou un programme parfait.'),
 P('De l’information aux protéines','Dans un schéma général, une région d’ADN est transcrite en ARN ; certains ARN servent à fabriquer des protéines. L’expression des gènes dépend également de mécanismes de régulation et du contexte cellulaire.','Posséder un gène ne signifie pas l’exprimer constamment.'),
 P('Ce qu’est une mutation','Une mutation est une modification de la séquence de l’ADN. Elle peut être sans effet notable, nuisible ou parfois avantageuse selon l’environnement. La variation génétique participe aux mécanismes de l’évolution.','Mutation ne signifie pas automatiquement maladie.')],[
 Q('De quoi est constitué l’ADN ?',['De nucléotides','De globules rouges','De cellules entières','De protéines uniquement'],0,'Les nucléotides sont les unités constitutives de l’ADN.'),
 Q('Quel intermédiaire intervient souvent entre ADN et synthèse protéique ?',['Le glucose','L’ARN','Le calcium','La cellulose'],1,'Les ARN messagers transportent l’information utilisée lors de la synthèse des protéines.'),
 Q('Une mutation entraîne-t-elle nécessairement une maladie ?',['Oui, dans tous les cas','Oui, chez les plantes uniquement','Non, ses effets peuvent être variés','Non, car les mutations n’existent pas'],2,'Beaucoup de mutations n’ont pas d’effet pathologique identifiable.')]),
L('biais','ideas',2,'Pourquoi notre cerveau cherche à avoir raison','Le biais de confirmation au quotidien','🪞',[
 P('Une préférence discrète','Le biais de confirmation désigne la tendance à rechercher, interpréter ou retenir plus facilement les éléments qui confortent une croyance préexistante. Cette tendance peut toucher tout le monde, y compris les personnes expertes.','Être informé n’immunise pas contre les biais.'),
 P('Un exemple concret','Si tu es persuadé qu’une politique a échoué, tu risques de remarquer surtout les données défavorables. Les résultats contraires peuvent être minimisés ou jugés moins crédibles sans analyse équivalente.','Le problème porte sur le traitement asymétrique des preuves.'),
 P('Une méthode de défense','Formule à l’avance ce qui te ferait changer d’avis. Recherche activement une source sérieuse soutenant la position opposée et compare les données. Cela ne signifie pas considérer toutes les thèses comme également solides.','L’esprit critique consiste aussi à examiner ses propres conclusions.')],[
 Q('Qu’appelle-t-on biais de confirmation ?',['Une mémorisation parfaite','Une préférence pour les informations qui confirment nos croyances','Un calcul de probabilité','Une erreur réservée aux novices'],1,'Ce biais influence la sélection et l’interprétation des informations.'),
 Q('Quelle pratique aide à le limiter ?',['Chercher des éléments capables de contredire son hypothèse','Lire uniquement des avis similaires','Ignorer les données chiffrées','Choisir une conclusion avant de regarder les faits'],0,'La recherche de preuves contradictoires réduit le risque d’analyse unilatérale.'),
 Q('Que suppose une attitude critique ?',['Que toutes les idées sont identiques','Que la première opinion est toujours juste','Que l’on examine aussi ses propres croyances','Que les experts ne commettent jamais d’erreur'],2,'L’examen critique doit aussi porter sur nos propres hypothèses.')]),
L('contrat','ideas',3,'Le contrat social : qui rend le pouvoir légitime ?','Hobbes, Locke et Rousseau en dialogue','📖',[
 P('Une même question','Les théories du contrat social cherchent à expliquer à quelles conditions l’autorité politique est légitime. Elles imaginent souvent un état de nature pour réfléchir au passage vers une société politique. Il s’agit d’un outil conceptuel, pas nécessairement d’un épisode historique réel.','Une fiction philosophique peut permettre un raisonnement rigoureux.'),
 P('Trois réponses distinctes','Chez Hobbes, un pouvoir souverain fort répond au danger de la guerre de tous contre tous. Locke met l’accent sur des droits et sur un pouvoir limité par sa finalité protectrice. Rousseau examine la souveraineté populaire et la volonté générale.','Les auteurs partagent une question mais défendent des solutions divergentes.'),
 P('Des débats toujours actuels','Comment protéger la sécurité sans sacrifier la liberté ? Quand un gouvernement perd-il sa légitimité ? Les termes du débat contemporain ne sont pas identiques à ceux du XVIIe et du XVIIIe siècle, mais les tensions restent fécondes.','Sécurité, droits et souveraineté ne se concilient pas automatiquement.')],[
 Q('Quel auteur défend un souverain puissant comme réponse à l’insécurité de l’état de nature ?',['Hobbes','Rousseau','John Stuart Mill','Simone de Beauvoir'],0,'Hobbes associe le souverain à la sortie d’une situation de violence potentielle.'),
 Q('Quel penseur insiste particulièrement sur les droits individuels et un pouvoir politique limité ?',['Platon','Locke','Hegel','Nietzsche'],1,'Locke défend une autorité politique liée à la protection des droits.'),
 Q('Quel concept est central chez Rousseau ?',['L’impératif catégorique','L’utilitarisme','La volonté générale','La sélection naturelle'],2,'La volonté générale occupe une place centrale dans sa théorie de la souveraineté.')]),
L('entropie','ideas',3,'L’entropie sans équations compliquées','Ordre, énergie et irréversibilité','🌡️',[
 P('Une grandeur physique','En thermodynamique, l’entropie caractérise notamment la dispersion de l’énergie et le nombre de configurations microscopiques compatibles avec un état macroscopique. La notion est plus précise que la simple idée de « désordre ».','Le mot entropie a un sens technique précis en physique.'),
 P('Le sens privilégié des évolutions','Dans un système isolé, l’entropie totale ne diminue pas spontanément. Cette formulation du second principe aide à comprendre pourquoi la chaleur se transfère spontanément d’un corps plus chaud vers un plus froid.','« Spontanément » et « système isolé » sont des conditions essentielles.'),
 P('Pourquoi les structures restent possibles','Des structures localement ordonnées peuvent apparaître si elles échangent matière ou énergie avec leur environnement. Un réfrigérateur refroidit son intérieur en consommant de l’électricité et en rejetant de la chaleur à l’extérieur.','Une diminution locale d’entropie ne contredit pas le second principe.')],[
 Q('Dans quel type de système l’entropie totale ne diminue-t-elle pas spontanément ?',['Un système isolé','N’importe quel objet sans condition','Une pièce avec la fenêtre ouverte','Un circuit alimenté par le secteur'],0,'Le second principe porte notamment sur les systèmes isolés.'),
 Q('Quel phénomène est spontanément observé entre un corps chaud et un corps froid ?',['La chaleur circule toujours du froid vers le chaud','La chaleur passe du chaud vers le froid','Les températures deviennent infinies','L’énergie cesse d’exister'],1,'La chaleur se transfère spontanément du corps le plus chaud vers le plus froid.'),
 Q('Pourquoi un réfrigérateur ne contredit-il pas le second principe ?',['Il crée de l’énergie','Il est parfaitement isolé et sans moteur','Il consomme de l’énergie et rejette de la chaleur','Son intérieur n’a pas de température'],2,'Le refroidissement local demande un travail et s’accompagne de rejets thermiques.')])
];
